185	uint64_t DIE::getDebugSectionOffset() const {
186	  const DIEUnit *Unit = getUnit();
187	  assert(Unit && "DIE must be owned by a DIEUnit to get its absolute offset");
188	  return Unit->getDebugSectionOffset() + getOffset();
189	}
