1759	/// Extracts a numeric type identifier of a Function's type from
1760	/// callgraph metadata. Returns null if metadata cannot be found.
1761	static ConstantInt *extractNumericCGTypeId(const Function &F) {
1762	  SmallVector<MDNode *, 2> Types;
1763	  F.getMetadata(LLVMContext::MD_callgraph, Types);
1764	  for (const auto &Type : Types) {
1765	    if (Type->getNumOperands() == 1 && isa<MDString>(Type->getOperand(0))) {
1766	      MDString *MDTypeId = cast<MDString>(Type->getOperand(0));
1767	      uint64_t TypeIdVal = llvm::MD5Hash(MDTypeId->getString());
1768	      IntegerType *Int64Ty = Type::getInt64Ty(F.getContext());
1769	      return ConstantInt::get(Int64Ty, TypeIdVal);
1770	    }
1771	  }
1772	  return nullptr;
1773	}
1774	
1775	/// Emits .llvm.callgraph section.
1776	void AsmPrinter::emitCallGraphSection(const MachineFunction &MF,
1777	                                      FunctionCallGraphInfo &FuncCGInfo) {
1778	  if (!MF.getTarget().Options.EmitCallGraphSection)
1779	    return;
1780	
1781	  // Switch to the call graph section for the function
1782	  MCSection *FuncCGSection =
1783	      getObjFileLowering().getCallGraphSection(*getCurrentSection());
1784	  assert(FuncCGSection && "null callgraph section");
1785	  OutStreamer->pushSection();
1786	  OutStreamer->switchSection(FuncCGSection);
1787	
1788	  const Function &F = MF.getFunction();
1789	  // If this function has external linkage or has its address taken and
1790	  // it is not a callback, then anything could call it.
1791	  bool IsIndirectTarget =
1792	      !F.hasLocalLinkage() || F.hasAddressTaken(nullptr,
1793	                                                /*IgnoreCallbackUses=*/true,
1794	                                                /*IgnoreAssumeLikeCalls=*/true,
1795	                                                /*IgnoreLLVMUsed=*/false);
1796	
1797	  const auto &DirectCallees = FuncCGInfo.DirectCallees;
1798	  const auto &IndirectCalleeTypeIDs = FuncCGInfo.IndirectCalleeTypeIDs;
1799	
1800	  using namespace callgraph;
1801	  Flags CGFlags = Flags::None;
1802	  if (IsIndirectTarget)
1803	    CGFlags |= Flags::IsIndirectTarget;
1804	  if (DirectCallees.size() > 0)
1805	    CGFlags |= Flags::HasDirectCallees;
1806	  if (IndirectCalleeTypeIDs.size() > 0)
1807	    CGFlags |= Flags::HasIndirectCallees;
1808	
1809	  // Emit function's call graph information.
1810	  // 1) CallGraphSectionFormatVersion
1811	  // 2) Flags
1812	  //    a. LSB bit 0 is set to 1 if the function is a potential indirect
1813	  //       target.
1814	  //    b. LSB bit 1 is set to 1 if there are direct callees.
1815	  //    c. LSB bit 2 is set to 1 if there are indirect callees.
1816	  //    d. Rest of the 5 bits in Flags are reserved for any future use.
1817	  // 3) Function entry PC.
1818	  // 4) FunctionTypeID if the function is indirect target and its type id
1819	  //    is known, otherwise it is set to 0.
1820	  // 5) Number of unique direct callees, if at least one exists.
1821	  // 6) For each unique direct callee, the callee's PC.
1822	  // 7) Number of unique indirect target type IDs, if at least one exists.
1823	  // 8) Each unique indirect target type id.
1824	  OutStreamer->emitInt8(CallGraphSectionFormatVersion::V_0);
1825	  OutStreamer->emitInt8(static_cast<uint8_t>(CGFlags));
1826	  OutStreamer->emitSymbolValue(getSymbol(&F), TM.getProgramPointerSize());
1827	  const auto *TypeId = extractNumericCGTypeId(F);
1828	  if (IsIndirectTarget && TypeId)
1829	    OutStreamer->emitInt64(TypeId->getZExtValue());
1830	  else
1831	    OutStreamer->emitInt64(0);
1832	
1833	  if (DirectCallees.size() > 0) {
1834	    OutStreamer->emitULEB128IntValue(DirectCallees.size());
1835	    for (const auto &CalleeSymbol : DirectCallees)
1836	      OutStreamer->emitSymbolValue(CalleeSymbol, TM.getProgramPointerSize());
1837	    FuncCGInfo.DirectCallees.clear();
1838	  }
1839	  if (IndirectCalleeTypeIDs.size() > 0) {
1840	    OutStreamer->emitULEB128IntValue(IndirectCalleeTypeIDs.size());
1841	    for (const auto &CalleeTypeId : IndirectCalleeTypeIDs)
1842	      OutStreamer->emitInt64(CalleeTypeId);
1843	    FuncCGInfo.IndirectCalleeTypeIDs.clear();
1844	  }
1845	  // End of emitting call graph section contents.
1846	  OutStreamer->popSection();
1847	}
