1855	
1856	void AsmPrinter::emitPCSections(const MachineFunction &MF) {
1857	  const Function &F = MF.getFunction();
1858	  if (PCSectionsSymbols.empty() && !F.hasMetadata(LLVMContext::MD_pcsections))
1859	    return;
1860	
1861	  const CodeModel::Model CM = MF.getTarget().getCodeModel();
1862	  const unsigned RelativeRelocSize =
1863	      (CM == CodeModel::Medium || CM == CodeModel::Large) ? getPointerSize()
1864	                                                          : 4;
1865	
1866	  // Switch to PCSection, short-circuiting the common case where the current
1867	  // section is still valid (assume most MD_pcsections contain just 1 section).
1868	  auto SwitchSection = [&, Prev = StringRef()](const StringRef &Sec) mutable {
1869	    if (Sec == Prev)
1870	      return;
1871	    MCSection *S = getObjFileLowering().getPCSection(Sec, MF.getSection());
1872	    assert(S && "PC section is not initialized");
1873	    OutStreamer->switchSection(S);
1874	    Prev = Sec;
1875	  };
1876	  // Emit symbols into sections and data as specified in the pcsections MDNode.
1877	  auto EmitForMD = [&](const MDNode &MD, ArrayRef<const MCSymbol *> Syms,
1878	                       bool Deltas) {
1879	    // Expect the first operand to be a section name. After that, a tuple of
1880	    // constants may appear, which will simply be emitted into the current
1881	    // section (the user of MD_pcsections decides the format of encoded data).
1882	    assert(isa<MDString>(MD.getOperand(0)) && "first operand not a string");
1883	    bool ConstULEB128 = false;
1884	    for (const MDOperand &MDO : MD.operands()) {
1885	      if (auto *S = dyn_cast<MDString>(MDO)) {
1886	        // Found string, start of new section!
1887	        // Find options for this section "<section>!<opts>" - supported options:
1888	        //   C = Compress constant integers of size 2-8 bytes as ULEB128.
1889	        const StringRef SecWithOpt = S->getString();
1890	        const size_t OptStart = SecWithOpt.find('!'); // likely npos
1891	        const StringRef Sec = SecWithOpt.substr(0, OptStart);
1892	        const StringRef Opts = SecWithOpt.substr(OptStart); // likely empty
1893	        ConstULEB128 = Opts.contains('C');
1894	#ifndef NDEBUG
1895	        for (char O : Opts)
1896	          assert((O == '!' || O == 'C') && "Invalid !pcsections options");
1897	#endif
1898	        SwitchSection(Sec);
1899	        const MCSymbol *Prev = Syms.front();
1900	        for (const MCSymbol *Sym : Syms) {
1901	          if (Sym == Prev || !Deltas) {
1902	            // Use the entry itself as the base of the relative offset.
1903	            MCSymbol *Base = MF.getContext().createTempSymbol("pcsection_base");
1904	            OutStreamer->emitLabel(Base);
1905	            // Emit relative relocation `addr - base`, which avoids a dynamic
1906	            // relocation in the final binary. User will get the address with
1907	            // `base + addr`.
1908	            emitLabelDifference(Sym, Base, RelativeRelocSize);
1909	          } else {
1910	            // Emit delta between symbol and previous symbol.
1911	            if (ConstULEB128)
1912	              emitLabelDifferenceAsULEB128(Sym, Prev);
1913	            else
1914	              emitLabelDifference(Sym, Prev, 4);
1915	          }
1916	          Prev = Sym;
1917	        }
1918	      } else {
1919	        // Emit auxiliary data after PC.
1920	        assert(isa<MDNode>(MDO) && "expecting either string or tuple");
1921	        const auto *AuxMDs = cast<MDNode>(MDO);
1922	        for (const MDOperand &AuxMDO : AuxMDs->operands()) {
1923	          assert(isa<ConstantAsMetadata>(AuxMDO) && "expecting a constant");
1924	          const Constant *C = cast<ConstantAsMetadata>(AuxMDO)->getValue();
1925	          const DataLayout &DL = F.getDataLayout();
1926	          const uint64_t Size = DL.getTypeStoreSize(C->getType());
1927	
1928	          if (auto *CI = dyn_cast<ConstantInt>(C);
1929	              CI && ConstULEB128 && Size > 1 && Size <= 8) {
1930	            emitULEB128(CI->getZExtValue());
1931	          } else {
1932	            emitGlobalConstant(DL, C);
1933	          }
1934	        }
1935	      }
1936	    }
1937	  };
1938	
1939	  OutStreamer->pushSection();
1940	  // Emit PCs for function start and function size.
1941	  if (const MDNode *MD = F.getMetadata(LLVMContext::MD_pcsections))
1942	    EmitForMD(*MD, {getFunctionBegin(), getFunctionEnd()}, true);
1943	  // Emit PCs for instructions collected.
1944	  for (const auto &MS : PCSectionsSymbols)
1945	    EmitForMD(*MS.first, MS.second, false);
1946	  OutStreamer->popSection();
1947	  PCSectionsSymbols.clear();
1948	}
