1950	/// Returns true if function begin and end labels should be emitted.
1951	static bool needFuncLabels(const MachineFunction &MF, const AsmPrinter &Asm) {
1952	  if (Asm.hasDebugInfo() || !MF.getLandingPads().empty() ||
1953	      MF.hasEHFunclets() ||
1954	      MF.getFunction().hasMetadata(LLVMContext::MD_pcsections))
1955	    return true;
1956	
1957	  // We might emit an EH table that uses function begin and end labels even if
1958	  // we don't have any landingpads.
1959	  if (!MF.getFunction().hasPersonalityFn())
1960	    return false;
1961	  return !isNoOpWithoutInvoke(
1962	      classifyEHPersonality(MF.getFunction().getPersonalityFn()));
1963	}
