1965	// Return the mnemonic of a MachineInstr if available, or the MachineInstr
1966	// opcode name otherwise.
1967	static StringRef getMIMnemonic(const MachineInstr &MI, MCStreamer &Streamer) {
1968	  const TargetInstrInfo *TII =
1969	      MI.getParent()->getParent()->getSubtarget().getInstrInfo();
1970	  MCInst MCI;
1971	  MCI.setOpcode(MI.getOpcode());
1972	  if (StringRef Name = Streamer.getMnemonic(MCI); !Name.empty())
1973	    return Name;
1974	  StringRef Name = TII->getName(MI.getOpcode());
1975	  assert(!Name.empty() && "Missing mnemonic and name for opcode");
1976	  return Name;
1977	}
