1979	void AsmPrinter::handleCallsiteForCallgraph(
1980	    FunctionCallGraphInfo &FuncCGInfo,
1981	    const MachineFunction::CallSiteInfoMap &CallSitesInfoMap,
1982	    const MachineInstr &MI) {
1983	  assert(MI.isCall() && "This method is meant for call instructions only.");
1984	  const MachineOperand &CalleeOperand = MI.getOperand(0);
1985	  if (CalleeOperand.isGlobal() || CalleeOperand.isSymbol()) {
1986	    // Handle direct calls.
1987	    MCSymbol *CalleeSymbol = nullptr;
1988	    switch (CalleeOperand.getType()) {
1989	    case llvm::MachineOperand::MO_GlobalAddress:
1990	      CalleeSymbol = getSymbol(CalleeOperand.getGlobal());
1991	      break;
1992	    case llvm::MachineOperand::MO_ExternalSymbol:
1993	      CalleeSymbol = GetExternalSymbolSymbol(CalleeOperand.getSymbolName());
1994	      break;
1995	    default:
1996	      llvm_unreachable(
1997	          "Expected to only handle direct call instructions here.");
1998	    }
1999	    FuncCGInfo.DirectCallees.insert(CalleeSymbol);
2000	    return; // Early exit after handling the direct call instruction.
2001	  }
2002	  const auto &CallSiteInfo = CallSitesInfoMap.find(&MI);
2003	  if (CallSiteInfo == CallSitesInfoMap.end())
2004	    return;
2005	  // Handle indirect callsite info.
2006	  // Only indirect calls have type identifiers set.
2007	  for (ConstantInt *CalleeTypeId : CallSiteInfo->second.CalleeTypeIds) {
2008	    uint64_t CalleeTypeIdVal = CalleeTypeId->getZExtValue();
2009	    FuncCGInfo.IndirectCalleeTypeIDs.insert(CalleeTypeIdVal);
2010	  }
2011	}
