2013	/// Helper to emit a symbol for the prefetch target associated with the given
2014	/// BBID and callsite index.
2015	void AsmPrinter::emitPrefetchTargetSymbol(const UniqueBBID &BBID,
2016	                                          unsigned CallsiteIndex) {
2017	  SmallString<128> FunctionName;
2018	  getNameWithPrefix(FunctionName, &MF->getFunction());
2019	  MCSymbol *PrefetchTargetSymbol = OutContext.getOrCreateSymbol(
2020	      getPrefetchTargetSymbolName(FunctionName, BBID, CallsiteIndex));
2021	  // If the function is weak-linkage it may be replaced by a strong
2022	  // version, in which case the prefetch targets should also be replaced.
2023	  OutStreamer->emitSymbolAttribute(
2024	      PrefetchTargetSymbol,
2025	      MF->getFunction().isWeakForLinker() ? MCSA_Weak : MCSA_Global);
2026	  OutStreamer->emitLabel(PrefetchTargetSymbol);
2027	}
