2029	/// Emit dangling prefetch targets that were not mapped to any basic block.
2030	void AsmPrinter::emitDanglingPrefetchTargets() {
2031	  const DenseMap<UniqueBBID, SmallVector<unsigned>> &MFPrefetchTargets =
2032	      MF->getPrefetchTargets();
2033	  if (MFPrefetchTargets.empty())
2034	    return;
2035	  DenseSet<UniqueBBID> MFBBIDs;
2036	  for (const MachineBasicBlock &MBB : *MF)
2037	    if (std::optional<UniqueBBID> BBID = MBB.getBBID())
2038	      MFBBIDs.insert(*BBID);
2039	
2040	  for (const auto &[BBID, CallsiteIndexes] : MFPrefetchTargets) {
2041	    if (MFBBIDs.contains(BBID))
2042	      continue;
2043	    for (unsigned CallsiteIndex : CallsiteIndexes)
2044	      emitPrefetchTargetSymbol(BBID, CallsiteIndex);
2045	  }
2046	}
