2048	/// EmitFunctionBody - This method emits the body and trailer for a
2049	/// function.
2050	void AsmPrinter::emitFunctionBody() {
2051	  emitFunctionHeader();
2052	
2053	  // Emit target-specific gunk before the function body.
2054	  emitFunctionBodyStart();
2055	
2056	  if (isVerbose()) {
2057	    MDT = GetMDT(*MF);
2058	    // Get MachineLoopInfo or compute it on the fly if it's unavailable, which
2059	    // needs a MachineDominatorTree only for an irreducible CFG.
2060	    MLI = GetMLI(*MF);
2061	    if (!MLI) {
2062	      OwnedMLI = std::make_unique<MachineLoopInfo>();
2063	      OwnedMLI->calculate(*MF, [&]() -> const MachineDominatorTree & {
2064	        if (!MDT) {
2065	          OwnedMDT = std::make_unique<MachineDominatorTree>();
2066	          OwnedMDT->recalculate(*MF);
2067	          MDT = OwnedMDT.get();
2068	        }
2069	        return *MDT;
2070	      });
2071	      MLI = OwnedMLI.get();
2072	    }
2073	  }
2074	
2075	  // Print out code for the function.
2076	  bool HasAnyRealCode = false;
2077	  int NumInstsInFunction = 0;
2078	  bool IsEHa = MMI->getModule()->getModuleFlag("eh-asynch");
2079	
2080	  const MCSubtargetInfo *STI = nullptr;
2081	  if (this->MF)
2082	    STI = &getSubtargetInfo();
2083	  else
2084	    STI = &TM.getMCSubtargetInfo();
2085	
2086	  bool CanDoExtraAnalysis = ORE->allowExtraAnalysis(DEBUG_TYPE);
2087	  // Create a slot for the entry basic block section so that the section
2088	  // order is preserved when iterating over MBBSectionRanges.
2089	  if (!MF->empty())
2090	    MBBSectionRanges[MF->front().getSectionID()] =
2091	        MBBSectionRange{CurrentFnBegin, nullptr};
2092	
2093	  FunctionCallGraphInfo FuncCGInfo;
2094	  const auto &CallSitesInfoMap = MF->getCallSitesInfo();
2095	
2096	  // Dangling targets are not mapped to any blocks and must be emitted at the
2097	  // beginning of the function.
2098	  emitDanglingPrefetchTargets();
2099	
2100	  const auto &MFPrefetchTargets = MF->getPrefetchTargets();
2101	  for (auto &MBB : *MF) {
2102	    // Print a label for the basic block.
2103	    emitBasicBlockStart(MBB);
2104	    DenseMap<StringRef, unsigned> MnemonicCounts;
2105	
2106	    const SmallVector<unsigned> *PrefetchTargets = nullptr;
2107	    if (auto BBID = MBB.getBBID()) {
2108	      auto R = MFPrefetchTargets.find(*BBID);
2109	      if (R != MFPrefetchTargets.end())
2110	        PrefetchTargets = &R->second;
2111	    }
2112	    auto PrefetchTargetIt =
2113	        PrefetchTargets ? PrefetchTargets->begin() : nullptr;
2114	    auto PrefetchTargetEnd = PrefetchTargets ? PrefetchTargets->end() : nullptr;
2115	    unsigned LastCallsiteIndex = 0;
2116	
2117	    for (auto &MI : MBB) {
2118	      if (PrefetchTargetIt != PrefetchTargetEnd &&
2119	          *PrefetchTargetIt == LastCallsiteIndex) {
2120	        emitPrefetchTargetSymbol(*MBB.getBBID(), *PrefetchTargetIt);
2121	        ++PrefetchTargetIt;
2122	      }
2123	
2124	      // Print the assembly for the instruction.
2125	      if (!MI.isPosition() && !MI.isImplicitDef() && !MI.isKill() &&
2126	          !MI.isDebugInstr()) {
2127	        HasAnyRealCode = true;
2128	      }
2129	
2130	      // If there is a pre-instruction symbol, emit a label for it here.
2131	      if (MCSymbol *S = MI.getPreInstrSymbol())
2132	        OutStreamer->emitLabel(S);
2133	
2134	      if (MDNode *MD = MI.getPCSections())
2135	        emitPCSectionsLabel(*MF, *MD);
2136	
2137	      for (auto &Handler : Handlers)
2138	        Handler->beginInstruction(&MI);
2139	
2140	      if (isVerbose())
2141	        emitComments(MI, STI, OutStreamer->getCommentOS());
2142	
2143	#ifndef NDEBUG
2144	      MCFragment *OldFragment = OutStreamer->getCurrentFragment();
2145	      size_t OldFragSize = OldFragment->getFixedSize();
2146	#endif
2147	
2148	      switch (MI.getOpcode()) {
2149	      case TargetOpcode::CFI_INSTRUCTION:
2150	        emitCFIInstruction(MI);
2151	        break;
2152	      case TargetOpcode::LOCAL_ESCAPE:
2153	        emitFrameAlloc(MI);
2154	        break;
2155	      case TargetOpcode::ANNOTATION_LABEL:
2156	      case TargetOpcode::GC_LABEL:
2157	        OutStreamer->emitLabel(MI.getOperand(0).getMCSymbol());
2158	        break;
2159	      case TargetOpcode::EH_LABEL:
2160	        OutStreamer->AddComment("EH_LABEL");
2161	        OutStreamer->emitLabel(MI.getOperand(0).getMCSymbol());
2162	        // For AsynchEH, insert a Nop if followed by a trap inst
2163	        //   Or the exception won't be caught.
2164	        //   (see MCConstantExpr::create(1,..) in WinException.cpp)
2165	        //  Ignore SDiv/UDiv because a DIV with Const-0 divisor
2166	        //    must have being turned into an UndefValue.
2167	        //  Div with variable opnds won't be the first instruction in
2168	        //  an EH region as it must be led by at least a Load
2169	        {
2170	          auto MI2 = std::next(MI.getIterator());
2171	          if (IsEHa && MI2 != MBB.end() &&
2172	              (MI2->mayLoadOrStore() || MI2->mayRaiseFPException()))
2173	            emitNops(1);
2174	        }
2175	        break;
2176	      case TargetOpcode::INLINEASM:
2177	      case TargetOpcode::INLINEASM_BR:
2178	        emitInlineAsm(&MI);
2179	        break;
2180	      case TargetOpcode::DBG_VALUE:
2181	      case TargetOpcode::DBG_VALUE_LIST:
2182	        if (isVerbose()) {
2183	          if (!emitDebugValueComment(&MI, *this))
2184	            emitInstruction(&MI);
2185	        }
2186	        break;
2187	      case TargetOpcode::DBG_INSTR_REF:
2188	        // This instruction reference will have been resolved to a machine
2189	        // location, and a nearby DBG_VALUE created. We can safely ignore
2190	        // the instruction reference.
2191	        break;

