1302	void DwarfDebug::finishEntityDefinitions() {
1303	  for (const auto &Entity : ConcreteEntities) {
1304	    DIE *Die = Entity->getDIE();
1305	    assert(Die);
1306	    // FIXME: Consider the time-space tradeoff of just storing the unit pointer
1307	    // in the ConcreteEntities list, rather than looking it up again here.
1308	    // DIE::getUnit isn't simple - it walks parent pointers, etc.
1309	    DwarfCompileUnit *Unit = CUDieMap.lookup(Die->getUnitDie());
1310	    assert(Unit);
1311	    Unit->finishEntityDefinition(Entity.get());
