1317	    assert(SP->getUnit()->getEmissionKind() != DICompileUnit::NoDebug);
1318	    forBothCUs(
1319	        getOrCreateDwarfCompileUnit(SP->getUnit()),
1320	        [&](DwarfCompileUnit &CU) { CU.finishSubprogramDefinition(SP); });
