1324	void DwarfDebug::finalizeModuleInfo() {
1325	  const TargetLoweringObjectFile &TLOF = Asm->getObjFileLowering();
1326	
1327	  finishSubprogramDefinitions();
1328	
1329	  finishEntityDefinitions();
1330	
1331	  bool HasEmittedSplitCU = false;
1332	
1333	  // Handle anything that needs to be done on a per-unit basis after
1334	  // all other generation.
1335	  for (const auto &P : CUMap) {
1336	    auto &TheCU = *P.second;
1337	    if (TheCU.getCUNode()->isDebugDirectivesOnly())
1338	      continue;
1339	    TheCU.attachLexicalScopesAbstractOrigins();
1340	    // Emit DW_AT_containing_type attribute to connect types with their
1341	    // vtable holding type.
1342	    TheCU.constructContainingTypeDIEs();
1343	
1344	    // Add CU specific attributes if we need to add any.
1345	    // If we're splitting the dwarf out now that we've got the entire
1346	    // CU then add the dwo id to it.
1347	    auto *SkCU = TheCU.getSkeleton();
1348	
1349	    bool HasSplitUnit = SkCU && !TheCU.getUnitDie().children().empty();
1350	
1351	    if (HasSplitUnit) {
1352	      (void)HasEmittedSplitCU;
1353	      assert((shareAcrossDWOCUs() || !HasEmittedSplitCU) &&
1354	             "Multiple CUs emitted into a single dwo file");
1355	      HasEmittedSplitCU = true;
1356	      dwarf::Attribute attrDWOName = getDwarfVersion() >= 5
1357	                                         ? dwarf::DW_AT_dwo_name
1358	                                         : dwarf::DW_AT_GNU_dwo_name;
1359	      finishUnitAttributes(TheCU.getCUNode(), TheCU);
1360	      StringRef DWOName = Asm->TM.Options.MCOptions.SplitDwarfFile;
1361	      TheCU.addString(TheCU.getUnitDie(), attrDWOName, DWOName);
1362	      SkCU->addString(SkCU->getUnitDie(), attrDWOName, DWOName);
1363	      // Emit a unique identifier for this CU. Include the DWO file name in the
1364	      // hash to avoid the case where two (almost) empty compile units have the
1365	      // same contents. This can happen if link-time optimization removes nearly
1366	      // all (unused) code from a CU.
1367	      uint64_t ID =
1368	          DIEHash(Asm, &TheCU).computeCUSignature(DWOName, TheCU.getUnitDie());
1369	      if (getDwarfVersion() >= 5) {
1370	        TheCU.setDWOId(ID);
1371	        SkCU->setDWOId(ID);
1372	      } else {
1373	        TheCU.addUInt(TheCU.getUnitDie(), dwarf::DW_AT_GNU_dwo_id,
1374	                      dwarf::DW_FORM_data8, ID);
1375	        SkCU->addUInt(SkCU->getUnitDie(), dwarf::DW_AT_GNU_dwo_id,
1376	                      dwarf::DW_FORM_data8, ID);
1377	      }
1378	
1379	      if (getDwarfVersion() < 5 && !SkeletonHolder.getRangeLists().empty()) {
1380	        const MCSymbol *Sym = TLOF.getDwarfRangesSection()->getBeginSymbol();
1381	        SkCU->addSectionLabel(SkCU->getUnitDie(), dwarf::DW_AT_GNU_ranges_base,
1382	                              Sym, Sym);
1383	      }
1384	    } else if (SkCU) {
1385	      finishUnitAttributes(SkCU->getCUNode(), *SkCU);
1386	    }
1387	
1388	    // If we have code split among multiple sections or non-contiguous
1389	    // ranges of code then emit a DW_AT_ranges attribute on the unit that will
1390	    // remain in the .o file, otherwise add a DW_AT_low_pc.
1391	    // FIXME: We should use ranges allow reordering of code ala
1392	    // .subsections_via_symbols in mach-o. This would mean turning on
1393	    // ranges for all subprogram DIEs for mach-o.
1394	    DwarfCompileUnit &U = SkCU ? *SkCU : TheCU;
1395	
1396	    if (unsigned NumRanges = TheCU.getRanges().size()) {
1397	      if (shouldAttachCompileUnitRanges()) {
1398	        if (NumRanges > 1 && useRangesSection())
1399	          // A DW_AT_low_pc attribute may also be specified in combination with
1400	          // DW_AT_ranges to specify the default base address for use in
1401	          // location lists (see Section 2.6.2) and range lists (see Section
1402	          // 2.17.3).
1403	          U.addUInt(U.getUnitDie(), dwarf::DW_AT_low_pc, dwarf::DW_FORM_addr,
1404	                    0);
1405	        else
1406	          U.setBaseAddress(TheCU.getRanges().front().Begin);
1407	        U.attachRangesOrLowHighPC(U.getUnitDie(), TheCU.takeRanges());
1408	      }
1409	    }
1410	
1411	    // We don't keep track of which addresses are used in which CU so this
1412	    // is a bit pessimistic under LTO.
1413	    if ((HasSplitUnit || getDwarfVersion() >= 5) && !AddrPool.isEmpty())
1414	      U.addAddrTableBase();
1415	
1416	    if (getDwarfVersion() >= 5) {
1417	      if (U.hasRangeLists())
1418	        U.addRnglistsBase();
1419	
1420	      if (!DebugLocs.getLists().empty() && !useSplitDwarf()) {
1421	        U.addSectionLabel(U.getUnitDie(), dwarf::DW_AT_loclists_base,
1422	                          DebugLocs.getSym(),
1423	                          TLOF.getDwarfLoclistsSection()->getBeginSymbol());
1424	      }
1425	    }
1426	
1427	    auto *CUNode = cast<DICompileUnit>(P.first);
1428	    // If compile Unit has macros, emit "DW_AT_macro_info/DW_AT_macros"
1429	    // attribute.
1430	    if (CUNode->getMacros()) {
1431	      if (UseDebugMacroSection) {
1432	        if (useSplitDwarf())
1433	          TheCU.addSectionDelta(
1434	              TheCU.getUnitDie(), dwarf::DW_AT_macros, U.getMacroLabelBegin(),
1435	              TLOF.getDwarfMacroDWOSection()->getBeginSymbol());
1436	        else {
1437	          dwarf::Attribute MacrosAttr = getDwarfVersion() >= 5
1438	                                            ? dwarf::DW_AT_macros
1439	                                            : dwarf::DW_AT_GNU_macros;
1440	          U.addSectionLabel(U.getUnitDie(), MacrosAttr, U.getMacroLabelBegin(),
1441	                            TLOF.getDwarfMacroSection()->getBeginSymbol());
1442	        }
1443	      } else {
1444	        if (useSplitDwarf())
1445	          TheCU.addSectionDelta(
1446	              TheCU.getUnitDie(), dwarf::DW_AT_macro_info,
1447	              U.getMacroLabelBegin(),
1448	              TLOF.getDwarfMacinfoDWOSection()->getBeginSymbol());
1449	        else
1450	          U.addSectionLabel(U.getUnitDie(), dwarf::DW_AT_macro_info,
1451	                            U.getMacroLabelBegin(),
1452	                            TLOF.getDwarfMacinfoSection()->getBeginSymbol());
1453	      }
1454	    }
1455	  }
1456	
1457	  // Emit all frontend-produced Skeleton CUs, i.e., Clang modules.
1458	  for (auto *CUNode : MMI->getModule()->debug_compile_units())
1459	    if (CUNode->getDWOId())
1460	      getOrCreateDwarfCompileUnit(CUNode);
1461	
1462	  // Compute DIE offsets and sizes.
1463	  InfoHolder.computeSizeAndOffsets();
1464	  if (useSplitDwarf())
1465	    SkeletonHolder.computeSizeAndOffsets();
1466	
1467	  // Now that offsets are computed, can replace DIEs in debug_names Entry with
1468	  // an actual offset.
1469	  AccelDebugNames.convertDieToOffset();
1470	}
