1472	// Emit all Dwarf sections that should come after the content.
1473	void DwarfDebug::endModule() {
1474	  // Terminate the pending line table.
1475	  if (PrevCU)
1476	    terminateLineTable(PrevCU);
1477	  PrevCU = nullptr;
1478	  assert(CurFn == nullptr);
1479	  assert(CurMI == nullptr);
1480	
1481	  const Module *M = MMI->getModule();
1482	
1483	  // Collect global variables info.
1484	  DenseMap<DIGlobalVariable *, SmallVector<DwarfCompileUnit::GlobalExpr, 1>>
1485	      GVMap;
1486	  for (const GlobalVariable &Global : M->globals()) {
1487	    SmallVector<DIGlobalVariableExpression *, 1> GVs;
1488	    Global.getDebugInfo(GVs);
1489	    for (auto *GVE : GVs)
1490	      GVMap[GVE->getVariable()].push_back({&Global, GVE->getExpression()});
1491	  }
1492	
1493	  for (DICompileUnit *CUNode : M->debug_compile_units()) {
1494	    DwarfCompileUnit *CU = getDwarfCompileUnit(CUNode);
1495	
1496	    // If the CU hasn't been emitted yet, it must be empty. Skip it.
1497	    if (!CU)
1498	      continue;
1499	
1500	    // Emit Global Variables.
1501	    for (auto *GVE : CUNode->getGlobalVariables()) {
1502	      // Don't bother adding DIGlobalVariableExpressions listed in the CU if we
1503	      // already know about the variable and it isn't adding a constant
1504	      // expression.
1505	      auto &GVMapEntry = GVMap[GVE->getVariable()];
1506	      auto *Expr = GVE->getExpression();
1507	      if (!GVMapEntry.size() || (Expr && Expr->isConstant()))
1508	        GVMapEntry.push_back({nullptr, Expr});
1509	    }
1510	    DenseSet<DIGlobalVariable *> Processed;
1511	    for (auto *GVE : CUNode->getGlobalVariables()) {
1512	      DIGlobalVariable *GV = GVE->getVariable();
1513	      assert(!isa_and_nonnull<DILocalScope>(GV->getScope()) &&
1514	             "Unexpected function-local entity in 'globals' CU field.");
1515	      if (Processed.insert(GV).second)
1516	        CU->getOrCreateGlobalVariableDIE(GV, sortGlobalExprs(GVMap[GV]));
1517	    }
1518	
1519	    // Emit types.
1520	    for (auto *Ty : CUNode->getEnumTypes()) {
1521	      assert(!isa_and_nonnull<DILocalScope>(Ty->getScope()) &&
1522	             "Unexpected function-local entity in 'enums' CU field.");
1523	      CU->getOrCreateTypeDIE(cast<DIType>(Ty));
1524	    }
1525	
1526	    for (auto *Ty : CUNode->getRetainedTypes()) {
1527	      if (DIType *RT = dyn_cast<DIType>(Ty)) {
1528	        // There is no point in force-emitting a forward declaration.
1529	        CU->getOrCreateTypeDIE(RT);
1530	      }
1531	    }
1532	
1533	    // Emit imported entities.
1534	    for (auto *IE : CUNode->getImportedEntities()) {
1535	      assert(!isa_and_nonnull<DILocalScope>(IE->getScope()) &&
1536	             "Unexpected function-local entity in 'imports' CU field.");
1537	      CU->getOrCreateImportedEntityDIE(IE);
1538	    }
1539	
1540	    // Emit function-local entities.
1541	    const auto Unexpected = [](const Metadata *N) {
1542	      llvm_unreachable("Unexpected local retained node!");
1543	    };
1544	    for (const auto *D : CU->getDeferredLocalDecls())
1545	      DISubprogram::visitRetainedNode<void>(
1546	          D, Unexpected, Unexpected,
1547	          [CU](const auto *IE) { CU->getOrCreateImportedEntityDIE(IE); },
1548	          [CU](const auto *Ty) { CU->getOrCreateTypeDIE(Ty); },
1549	          [&](const auto *GVE) {
1550	            DIGlobalVariable *GV = GVE->getVariable();
1551	            if (Processed.insert(GV).second)
1552	              CU->getOrCreateGlobalVariableDIE(GV, sortGlobalExprs(GVMap[GV]));
1553	          },
1554	          Unexpected);
1555	
1556	    // Emit base types.
1557	    CU->createBaseTypeDIEs();
1558	  }
1559	
1560	  // If we aren't actually generating debug info (check beginModule -
1561	  // conditionalized on the presence of the llvm.dbg.cu metadata node)
1562	  if (!Asm || !Asm->hasDebugInfo())
1563	    return;
1564	
1565	  // Finalize the debug info for the module.
1566	  finalizeModuleInfo();
1567	
1568	  if (useSplitDwarf())
1569	    // Emit debug_loc.dwo/debug_loclists.dwo section.
1570	    emitDebugLocDWO();
1571	  else
1572	    // Emit debug_loc/debug_loclists section.
1573	    emitDebugLoc();
1574	
1575	  // Corresponding abbreviations into a abbrev section.
1576	  emitAbbreviations();
1577	
1578	  // Emit all the DIEs into a debug info section.
1579	  emitDebugInfo();
1580	
1581	  // Emit info into a debug aranges section.
1582	  if (UseARangesSection)
1583	    emitDebugARanges();
1584	
1585	  // Emit info into a debug ranges section.
1586	  emitDebugRanges();
1587	
1588	  if (useSplitDwarf())
1589	  // Emit info into a debug macinfo.dwo section.
1590	    emitDebugMacinfoDWO();
1591	  else
1592	    // Emit info into a debug macinfo/macro section.
1593	    emitDebugMacinfo();
1594	
1595	  emitDebugStr();
1596	
1597	  if (useSplitDwarf()) {
1598	    emitDebugStrDWO();
1599	    emitDebugInfoDWO();
1600	    emitDebugAbbrevDWO();
1601	    emitDebugLineDWO();
1602	    emitDebugRangesDWO();
1603	  }
1604	
1605	  emitDebugAddr();
1606	
1607	  // Emit info into the dwarf accelerator table sections.
1608	  switch (getAccelTableKind()) {
1609	  case AccelTableKind::Apple:
1610	    emitAccelNames();
1611	    emitAccelObjC();
1612	    emitAccelNamespaces();
1613	    emitAccelTypes();
1614	    break;
1615	  case AccelTableKind::Dwarf:
1616	    emitAccelDebugNames();
1617	    break;
1618	  case AccelTableKind::None:
1619	    break;
1620	  case AccelTableKind::Default:
1621	    llvm_unreachable("Default should have already been resolved.");
1622	  }
1623	
1624	  // Emit the pubnames and pubtypes sections if requested.
1625	  emitDebugPubSections();
1626	
1627	  // clean up.
1628	  // FIXME: AbstractVariables.clear();
1629	}
