1646	// Collect variable information from side table maintained by MF.
1647	void DwarfDebug::collectVariableInfoFromMFTable(
1648	    DwarfCompileUnit &TheCU, DenseSet<InlinedEntity> &Processed) {
1649	  SmallDenseMap<InlinedEntity, DbgVariable *> MFVars;
1650	  LLVM_DEBUG(dbgs() << "DwarfDebug: collecting variables from MF side table\n");
1651	  for (const auto &VI : Asm->MF->getVariableDbgInfo()) {
1652	    if (!VI.Var)
1653	      continue;
1654	    assert(VI.Var->isValidLocationForIntrinsic(VI.Loc) &&
1655	           "Expected inlined-at fields to agree");
1656	
1657	    InlinedEntity Var(VI.Var, VI.Loc->getInlinedAt());
1658	    Processed.insert(Var);
1659	    LexicalScope *Scope = LScopes.findLexicalScope(VI.Loc);
1660	
1661	    // If variable scope is not found then skip this variable.
1662	    if (!Scope) {
1663	      LLVM_DEBUG(dbgs() << "Dropping debug info for " << VI.Var->getName()
1664	                        << ", no variable scope found\n");
1665	      continue;
1666	    }
1667	
1668	    ensureAbstractEntityIsCreatedIfScoped(TheCU, Var.first, Scope->getScopeNode());
1669	
1670	    // If we have already seen information for this variable, add to what we
1671	    // already know.
1672	    if (DbgVariable *PreviousLoc = MFVars.lookup(Var)) {
1673	      auto *PreviousMMI = std::get_if<Loc::MMI>(PreviousLoc);
1674	      auto *PreviousEntryValue = std::get_if<Loc::EntryValue>(PreviousLoc);
1675	      // Previous and new locations are both stack slots (MMI).
1676	      if (PreviousMMI && VI.inStackSlot())
1677	        PreviousMMI->addFrameIndexExpr(VI.Expr, VI.getStackSlot());
1678	      // Previous and new locations are both entry values.
1679	      else if (PreviousEntryValue && VI.inEntryValueRegister())
1680	        PreviousEntryValue->addExpr(VI.getEntryValueRegister(), *VI.Expr);
1681	      else {
1682	        // Locations differ, this should (rarely) happen in optimized async
1683	        // coroutines.
1684	        // Prefer whichever location has an EntryValue.
1685	        if (PreviousLoc->holds<Loc::MMI>())
1686	          PreviousLoc->emplace<Loc::EntryValue>(VI.getEntryValueRegister(),
1687	                                                *VI.Expr);
1688	        LLVM_DEBUG(dbgs() << "Dropping debug info for " << VI.Var->getName()
1689	                          << ", conflicting fragment location types\n");
1690	      }
1691	      continue;
1692	    }
1693	
1694	    auto RegVar = std::make_unique<DbgVariable>(
1695	                    cast<DILocalVariable>(Var.first), Var.second);
1696	    if (VI.inStackSlot())
1697	      RegVar->emplace<Loc::MMI>(VI.Expr, VI.getStackSlot());
1698	    else
1699	      RegVar->emplace<Loc::EntryValue>(VI.getEntryValueRegister(), *VI.Expr);
1700	    LLVM_DEBUG(dbgs() << "Created DbgVariable for " << VI.Var->getName()
1701	                      << "\n");
1702	    InfoHolder.addScopeVariable(Scope, RegVar.get());
1703	    MFVars.insert({Var, RegVar.get()});
1704	    ConcreteEntities.push_back(std::move(RegVar));
1705	  }
1706	}
