1708	/// Determine whether a *singular* DBG_VALUE is valid for the entirety of its
1709	/// enclosing lexical scope. The check ensures there are no other instructions
1710	/// in the same lexical scope preceding the DBG_VALUE and that its range is
1711	/// either open or otherwise rolls off the end of the scope.
1712	static bool validThroughout(LexicalScopes &LScopes,
1713	                            const MachineInstr *DbgValue,
1714	                            const MachineInstr *RangeEnd,
1715	                            const InstructionOrdering &Ordering) {
1716	  assert(DbgValue->getDebugLoc() && "DBG_VALUE without a debug location");
1717	  auto MBB = DbgValue->getParent();
1718	  auto DL = DbgValue->getDebugLoc();
1719	  auto *LScope = LScopes.findLexicalScope(DL);
1720	  // Scope doesn't exist; this is a dead DBG_VALUE.
1721	  if (!LScope)
1722	    return false;
1723	  auto &LSRange = LScope->getRanges();
1724	  if (LSRange.size() == 0)
1725	    return false;
1726	
1727	  const MachineInstr *LScopeBegin = LSRange.front().first;
1728	  // If the scope starts before the DBG_VALUE then we may have a negative
1729	  // result. Otherwise the location is live coming into the scope and we
1730	  // can skip the following checks.
1731	  if (!Ordering.isBefore(DbgValue, LScopeBegin)) {
1732	    // Exit if the lexical scope begins outside of the current block.
1733	    if (LScopeBegin->getParent() != MBB)
1734	      return false;
1735	
1736	    MachineBasicBlock::const_reverse_iterator Pred(DbgValue);
1737	    for (++Pred; Pred != MBB->rend(); ++Pred) {
1738	      if (Pred->getFlag(MachineInstr::FrameSetup))
1739	        break;
1740	      auto PredDL = Pred->getDebugLoc();
1741	      if (!PredDL || Pred->isMetaInstruction())
1742	        continue;
1743	      // Check whether the instruction preceding the DBG_VALUE is in the same
1744	      // (sub)scope as the DBG_VALUE.
1745	      if (DL->getScope() == PredDL->getScope())
1746	        return false;
1747	      auto *PredScope = LScopes.findLexicalScope(PredDL);
1748	      if (!PredScope || LScope->dominates(PredScope))
1749	        return false;
1750	    }
1751	  }
1752	
1753	  // If the range of the DBG_VALUE is open-ended, report success.
1754	  if (!RangeEnd)
1755	    return true;
1756	
1757	  // Single, constant DBG_VALUEs in the prologue are promoted to be live
1758	  // throughout the function. This is a hack, presumably for DWARF v2 and not
1759	  // necessarily correct. It would be much better to use a dbg.declare instead
1760	  // if we know the constant is live throughout the scope.
1761	  if (MBB->pred_empty() &&
1762	      all_of(DbgValue->debug_operands(),
1763	             [](const MachineOperand &Op) { return Op.isImm(); }))
1764	    return true;
1765	
1766	  // Test if the location terminates before the end of the scope.
1767	  const MachineInstr *LScopeEnd = LSRange.back().second;
1768	  if (Ordering.isBefore(RangeEnd, LScopeEnd))
1769	    return false;
1770	
1771	  // There's a single location which starts at the scope start, and ends at or
1772	  // after the scope end.
1773	  return true;
1774	}
