1776	/// Build the location list for all DBG_VALUEs in the function that
1777	/// describe the same variable. The resulting DebugLocEntries will have
1778	/// strict monotonically increasing begin addresses and will never
1779	/// overlap. If the resulting list has only one entry that is valid
1780	/// throughout variable's scope return true.
1781	//
1782	// See the definition of DbgValueHistoryMap::Entry for an explanation of the
1783	// different kinds of history map entries. One thing to be aware of is that if
1784	// a debug value is ended by another entry (rather than being valid until the
1785	// end of the function), that entry's instruction may or may not be included in
1786	// the range, depending on if the entry is a clobbering entry (it has an
1787	// instruction that clobbers one or more preceding locations), or if it is an
1788	// (overlapping) debug value entry. This distinction can be seen in the example
1789	// below. The first debug value is ended by the clobbering entry 2, and the
1790	// second and third debug values are ended by the overlapping debug value entry
1791	// 4.
1792	//
1793	// Input:
1794	//
1795	//   History map entries [type, end index, mi]
1796	//
1797	// 0 |      [DbgValue, 2, DBG_VALUE $reg0, [...] (fragment 0, 32)]
1798	// 1 | |    [DbgValue, 4, DBG_VALUE $reg1, [...] (fragment 32, 32)]
1799	// 2 | |    [Clobber, $reg0 = [...], -, -]
1800	// 3   | |  [DbgValue, 4, DBG_VALUE 123, [...] (fragment 64, 32)]
1801	// 4        [DbgValue, ~0, DBG_VALUE @g, [...] (fragment 0, 96)]
1802	//
1803	// Output [start, end) [Value...]:
1804	//
1805	// [0-1)    [(reg0, fragment 0, 32)]
1806	// [1-3)    [(reg0, fragment 0, 32), (reg1, fragment 32, 32)]
1807	// [3-4)    [(reg1, fragment 32, 32), (123, fragment 64, 32)]
1808	// [4-)     [(@g, fragment 0, 96)]
1809	bool DwarfDebug::buildLocationList(SmallVectorImpl<DebugLocEntry> &DebugLoc,
1810	                                   const DbgValueHistoryMap::Entries &Entries) {
1811	  using OpenRange =
1812	      std::pair<DbgValueHistoryMap::EntryIndex, DbgValueLoc>;
1813	  SmallVector<OpenRange, 4> OpenRanges;
1814	  bool isSafeForSingleLocation = true;
1815	  const MachineInstr *StartDebugMI = nullptr;
1816	  const MachineInstr *EndMI = nullptr;
1817	
1818	  for (auto EB = Entries.begin(), EI = EB, EE = Entries.end(); EI != EE; ++EI) {
1819	    const MachineInstr *Instr = EI->getInstr();
1820	
1821	    // Remove all values that are no longer live.
1822	    size_t Index = std::distance(EB, EI);
1823	    erase_if(OpenRanges, [&](OpenRange &R) { return R.first <= Index; });
1824	
1825	    // If we are dealing with a clobbering entry, this iteration will result in
1826	    // a location list entry starting after the clobbering instruction.
1827	    const MCSymbol *StartLabel =
1828	        EI->isClobber() ? getLabelAfterInsn(Instr) : getLabelBeforeInsn(Instr);
1829	    assert(StartLabel &&
1830	           "Forgot label before/after instruction starting a range!");
1831	
1832	    const MCSymbol *EndLabel;
1833	    if (std::next(EI) == Entries.end()) {
1834	      const MachineBasicBlock &EndMBB = Asm->MF->back();
1835	      EndLabel = Asm->MBBSectionRanges[EndMBB.getSectionID()].EndLabel;
1836	      if (EI->isClobber())
1837	        EndMI = EI->getInstr();
1838	    }
1839	    else if (std::next(EI)->isClobber())
1840	      EndLabel = getLabelAfterInsn(std::next(EI)->getInstr());
1841	    else
1842	      EndLabel = getLabelBeforeInsn(std::next(EI)->getInstr());
1843	    assert(EndLabel && "Forgot label after instruction ending a range!");
1844	
1845	    if (EI->isDbgValue())
1846	      LLVM_DEBUG(dbgs() << "DotDebugLoc: " << *Instr << "\n");
1847	
1848	    // If this history map entry has a debug value, add that to the list of
1849	    // open ranges and check if its location is valid for a single value
1850	    // location.
1851	    if (EI->isDbgValue()) {
1852	      // Do not add undef debug values, as they are redundant information in
1853	      // the location list entries. An undef debug results in an empty location
1854	      // description. If there are any non-undef fragments then padding pieces
1855	      // with empty location descriptions will automatically be inserted, and if
1856	      // all fragments are undef then the whole location list entry is
1857	      // redundant.
1858	      if (!Instr->isUndefDebugValue()) {
1859	        auto Value = getDebugLocValue(Instr);
1860	        OpenRanges.emplace_back(EI->getEndIndex(), Value);
1861	
1862	        // TODO: Add support for single value fragment locations.
1863	        if (Instr->getDebugExpression()->isFragment())
1864	          isSafeForSingleLocation = false;
1865	
1866	        if (!StartDebugMI)
1867	          StartDebugMI = Instr;
1868	      } else {
1869	        isSafeForSingleLocation = false;
1870	      }
1871	    }
1872	
1873	    // Location list entries with empty location descriptions are redundant
1874	    // information in DWARF, so do not emit those.
1875	    if (OpenRanges.empty())
1876	      continue;
1877	
1878	    // Omit entries with empty ranges as they do not have any effect in DWARF.
1879	    if (StartLabel == EndLabel) {
1880	      LLVM_DEBUG(dbgs() << "Omitting location list entry with empty range.\n");
1881	      continue;
1882	    }
1883	
1884	    SmallVector<DbgValueLoc, 4> Values;
1885	    for (auto &R : OpenRanges)
1886	      Values.push_back(R.second);
1887	
1888	    // With Basic block sections, it is posssible that the StartLabel and the
1889	    // Instr are not in the same section.  This happens when the StartLabel is
1890	    // the function begin label and the dbg value appears in a basic block
1891	    // that is not the entry.  In this case, the range needs to be split to
1892	    // span each individual section in the range from StartLabel to EndLabel.
1893	    if (Asm->MF->hasBBSections() && StartLabel == Asm->getFunctionBegin() &&
1894	        !Instr->getParent()->sameSection(&Asm->MF->front())) {
1895	      for (const auto &[MBBSectionId, MBBSectionRange] :
1896	           Asm->MBBSectionRanges) {
1897	        if (Instr->getParent()->getSectionID() == MBBSectionId) {
1898	          DebugLoc.emplace_back(MBBSectionRange.BeginLabel, EndLabel, Values);
1899	          break;
1900	        }
1901	        DebugLoc.emplace_back(MBBSectionRange.BeginLabel,
1902	                              MBBSectionRange.EndLabel, Values);
1903	      }
1904	    } else {
1905	      DebugLoc.emplace_back(StartLabel, EndLabel, Values);
1906	    }
1907	
1908	    // Attempt to coalesce the ranges of two otherwise identical
1909	    // DebugLocEntries.
1910	    auto CurEntry = DebugLoc.rbegin();
1911	    LLVM_DEBUG({
1912	      dbgs() << CurEntry->getValues().size() << " Values:\n";
1913	      for (auto &Value : CurEntry->getValues())
1914	        Value.dump();
1915	      dbgs() << "-----\n";
1916	    });
1917	
1918	    auto PrevEntry = std::next(CurEntry);
1919	    if (PrevEntry != DebugLoc.rend() && PrevEntry->MergeRanges(*CurEntry))
1920	      DebugLoc.pop_back();
1921	  }
1922	
1923	  if (!isSafeForSingleLocation ||
1924	      !validThroughout(LScopes, StartDebugMI, EndMI, getInstOrdering()))
1925	    return false;
1926	
1927	  if (DebugLoc.size() == 1)
1928	    return true;
1929	
1930	  if (!Asm->MF->hasBBSections())
1931	    return false;
1932	
1933	  // Check here to see if loclist can be merged into a single range. If not,
1934	  // we must keep the split loclists per section.  This does exactly what
1935	  // MergeRanges does without sections.  We don't actually merge the ranges
1936	  // as the split ranges must be kept intact if this cannot be collapsed
1937	  // into a single range.
1938	  const MachineBasicBlock *RangeMBB = nullptr;
1939	  if (DebugLoc[0].getBeginSym() == Asm->getFunctionBegin())
1940	    RangeMBB = &Asm->MF->front();
1941	  else
1942	    RangeMBB = Entries.begin()->getInstr()->getParent();
1943	  auto RangeIt = Asm->MBBSectionRanges.find(RangeMBB->getSectionID());
1944	  assert(RangeIt != Asm->MBBSectionRanges.end() &&
1945	         "Range MBB not found in MBBSectionRanges!");
1946	  auto *CurEntry = DebugLoc.begin();
1947	  auto *NextEntry = std::next(CurEntry);
1948	  auto NextRangeIt = std::next(RangeIt);
1949	  while (NextEntry != DebugLoc.end()) {
1950	    if (NextRangeIt == Asm->MBBSectionRanges.end())
1951	      return false;
1952	    // CurEntry should end the current section and NextEntry should start
1953	    // the next section and the Values must match for these two ranges to be
1954	    // merged.  Do not match the section label end if it is the entry block
1955	    // section.  This is because the end label for the Debug Loc and the
1956	    // Function end label could be different.
1957	    if ((RangeIt->second.EndLabel != Asm->getFunctionEnd() &&
1958	         CurEntry->getEndSym() != RangeIt->second.EndLabel) ||
1959	        NextEntry->getBeginSym() != NextRangeIt->second.BeginLabel ||
1960	        CurEntry->getValues() != NextEntry->getValues())
1961	      return false;
1962	    RangeIt = NextRangeIt;
1963	    NextRangeIt = std::next(RangeIt);
1964	    CurEntry = NextEntry;
1965	    NextEntry = std::next(CurEntry);
1966	  }
1967	  return true;
1968	}
