1970	DbgEntity *DwarfDebug::createConcreteEntity(DwarfCompileUnit &TheCU,
1971	                                            LexicalScope &Scope,
1972	                                            const DINode *Node,
1973	                                            const DILocation *Location,
1974	                                            const MCSymbol *Sym) {
1975	  ensureAbstractEntityIsCreatedIfScoped(TheCU, Node, Scope.getScopeNode());
1976	  if (isa<const DILocalVariable>(Node)) {
1977	    ConcreteEntities.push_back(
1978	        std::make_unique<DbgVariable>(cast<const DILocalVariable>(Node),
1979	                                       Location));
1980	    InfoHolder.addScopeVariable(&Scope,
1981	        cast<DbgVariable>(ConcreteEntities.back().get()));
1982	  } else if (isa<const DILabel>(Node)) {
1983	    ConcreteEntities.push_back(
1984	        std::make_unique<DbgLabel>(cast<const DILabel>(Node),
1985	                                    Location, Sym));
1986	    InfoHolder.addScopeLabel(&Scope,
1987	        cast<DbgLabel>(ConcreteEntities.back().get()));
1988	  }
1989	  return ConcreteEntities.back().get();
1990	}
