1992	// Find variables for each lexical scope.
1993	void DwarfDebug::collectEntityInfo(DwarfCompileUnit &TheCU,
1994	                                   const DISubprogram *SP,
1995	                                   DenseSet<InlinedEntity> &Processed) {
1996	  // Grab the variable info that was squirreled away in the MMI side-table.
1997	  collectVariableInfoFromMFTable(TheCU, Processed);
1998	
1999	  for (const auto &I : DbgValues) {
2000	    InlinedEntity IV = I.first;
2001	    if (Processed.count(IV))
2002	      continue;
2003	
2004	    // Instruction ranges, specifying where IV is accessible.
2005	    const auto &HistoryMapEntries = I.second;
2006	
2007	    // Try to find any non-empty variable location. Do not create a concrete
2008	    // entity if there are no locations.
2009	    if (!DbgValues.hasNonEmptyLocation(HistoryMapEntries))
2010	      continue;
2011	
2012	    LexicalScope *Scope = nullptr;
2013	    const DILocalVariable *LocalVar = cast<DILocalVariable>(IV.first);
2014	    if (const DILocation *IA = IV.second)
2015	      Scope = LScopes.findInlinedScope(LocalVar->getScope(), IA);
2016	    else
2017	      Scope = LScopes.findLexicalScope(LocalVar->getScope());
2018	    // If variable scope is not found then skip this variable.
2019	    if (!Scope)
2020	      continue;
2021	
2022	    Processed.insert(IV);
2023	    DbgVariable *RegVar = cast<DbgVariable>(createConcreteEntity(TheCU,
2024	                                            *Scope, LocalVar, IV.second));
2025	
2026	    const MachineInstr *MInsn = HistoryMapEntries.front().getInstr();
2027	    assert(MInsn->isDebugValue() && "History must begin with debug value");
2028	
2029	    // Check if there is a single DBG_VALUE, valid throughout the var's scope.
2030	    // If the history map contains a single debug value, there may be an
2031	    // additional entry which clobbers the debug value.
2032	    size_t HistSize = HistoryMapEntries.size();
2033	    bool SingleValueWithClobber =
2034	        HistSize == 2 && HistoryMapEntries[1].isClobber();
2035	    if (HistSize == 1 || SingleValueWithClobber) {
2036	      const auto *End =
2037	          SingleValueWithClobber ? HistoryMapEntries[1].getInstr() : nullptr;
2038	      if (validThroughout(LScopes, MInsn, End, getInstOrdering())) {
2039	        RegVar->emplace<Loc::Single>(MInsn);
2040	        continue;
2041	      }
2042	    }
2043	
2044	    // Handle multiple DBG_VALUE instructions describing one variable.
2045	    DebugLocStream::ListBuilder List(DebugLocs, TheCU, *Asm, *RegVar);
2046	
2047	    // Build the location list for this variable.
2048	    SmallVector<DebugLocEntry, 8> Entries;
2049	    bool isValidSingleLocation = buildLocationList(Entries, HistoryMapEntries);
2050	
2051	    // Check whether buildLocationList managed to merge all locations to one
2052	    // that is valid throughout the variable's scope. If so, produce single
2053	    // value location.
2054	    if (isValidSingleLocation) {
2055	      RegVar->emplace<Loc::Single>(Entries[0].getValues()[0]);
2056	      continue;
2057	    }
2058	
2059	    // If the variable has a DIBasicType, extract it.  Basic types cannot have
2060	    // unique identifiers, so don't bother resolving the type with the
2061	    // identifier map.
2062	    const DIBasicType *BT = dyn_cast<DIBasicType>(
2063	        static_cast<const Metadata *>(LocalVar->getType()));
2064	
2065	    // Finalize the entry by lowering it into a DWARF bytestream.
2066	    for (auto &Entry : Entries)
2067	      Entry.finalize(*Asm, List, BT, TheCU);
2068	  }
2069	
2070	  // For each InlinedEntity collected from DBG_LABEL instructions, convert to
2071	  // DWARF-related DbgLabel.
2072	  for (const auto &I : DbgLabels) {
2073	    InlinedEntity IL = I.first;
2074	    const MachineInstr *MI = I.second;
2075	    if (MI == nullptr)
2076	      continue;
2077	
2078	    LexicalScope *Scope = nullptr;
2079	    const DILabel *Label = cast<DILabel>(IL.first);
2080	    // The scope could have an extra lexical block file.
2081	    const DILocalScope *LocalScope =
2082	        Label->getScope()->getNonLexicalBlockFileScope();
2083	    // Get inlined DILocation if it is inlined label.
2084	    if (const DILocation *IA = IL.second)
2085	      Scope = LScopes.findInlinedScope(LocalScope, IA);
2086	    else
2087	      Scope = LScopes.findLexicalScope(LocalScope);
2088	    // If label scope is not found then skip this label.
2089	    if (!Scope)
2090	      continue;
2091	
2092	    Processed.insert(IL);
2093	    /// At this point, the temporary label is created.
2094	    /// Save the temporary label to DbgLabel entity to get the
2095	    /// actually address when generating Dwarf DIE.
2096	    MCSymbol *Sym = getLabelBeforeInsn(MI);
2097	    createConcreteEntity(TheCU, *Scope, Label, IL.second, Sym);
2098	  }
