261	  DIEBlock *Block = new (DIEValueAllocator) DIEBlock;
262	  addIntToBlock(*Block, Val);
263	  Block->computeSize(Asm->getDwarfFormParams());
264	  addBlock(Die, Attribute, Block->BestForm(), Block);
265	}
