435	#define HANDLE_DIEVALUE_SMALL(T)                                               \
436	  case is##T:                                                                  \
437	    destruct<DIE##T>();                                                        \
438	    return;
439	#define HANDLE_DIEVALUE_LARGE(T)                                               \
440	  case is##T:                                                                  \
441	    destruct<const DIE##T *>();                                                \
442	    return;
