457	  case is##T:                                                                  \
458	    construct<DIE##T>(*X.get<DIE##T>());                                       \
459	    return;
460	#define HANDLE_DIEVALUE_LARGE(T)                                               \
461	  case is##T:                                                                  \
462	    construct<const DIE##T *>(*X.get<const DIE##T *>());                       \
463	    return;
464	#include "llvm/CodeGen/DIEValue.def"
465	    }
466	  }
