541	struct IntrusiveBackListBase {
542	  using Node = IntrusiveBackListNode;
543	
544	  Node *Last = nullptr;
545	
546	  bool empty() const { return !Last; }
547	
548	  void push_back(Node &N) {
549	    assert(N.Next.getPointer() == &N && "Expected unlinked node");
550	    assert(N.Next.getInt() == true && "Expected unlinked node");
551	
552	    if (Last) {
553	      N.Next = Last->Next;
554	      Last->Next.setPointerAndInt(&N, false);
555	    }
556	    Last = &N;
557	  }
558	
559	  void push_front(Node &N) {
560	    assert(N.Next.getPointer() == &N && "Expected unlinked node");
561	    assert(N.Next.getInt() == true && "Expected unlinked node");
562	
563	    if (Last) {
564	      N.Next.setPointerAndInt(Last->Next.getPointer(), false);
565	      Last->Next.setPointerAndInt(&N, true);
566	    } else {
567	      Last = &N;
568	    }
569	  }
570	
571	  /// Delete node \p N by walking through the list until \p N's predecessor is
572	  /// found. Remove \p N from the list by updating the predecessor's next
573	  /// pointer and reset \p N's next pointer to itself.
574	  bool deleteNode(Node &N) {
575	    if (!Last)
576	      return false;
577	
578	    Node *Cur = Last;
579	    while (Cur->Next.getPointer() != &N) {
580	      Cur = Cur->Next.getPointer();
581	      if (Cur->Next.getInt())
582	        return false;
583	    }
584	
585	    Node *Target = Cur->Next.getPointer();
586	    if (Target == Cur) {
587	      Last = nullptr;
588	    } else if (Target == Last) {
589	      Cur->Next.setPointerAndInt(Target->Next.getPointer(), true);
590	      Last = Cur;
591	    } else {
592	      Cur->Next.setPointer(Target->Next.getPointer());
593	    }
594	
595	    Target->Next.setPointerAndInt(Target, true);
596	    return true;
597	  }
598	};
