601	public:
602	  using IntrusiveBackListBase::empty;
603	
604	  void push_back(T &N) { IntrusiveBackListBase::push_back(N); }
605	  void push_front(T &N) { IntrusiveBackListBase::push_front(N); }
606	
607	  T &back() { return *static_cast<T *>(Last); }
608	  const T &back() const { return *static_cast<T *>(Last); }
609	  T &front() {
610	    return *static_cast<T *>(Last ? Last->Next.getPointer() : nullptr);
611	  }
