616	  void takeNodes(IntrusiveBackList<T> &Other) {
617	    if (Other.empty())
618	      return;
619	
620	    T *FirstNode = static_cast<T *>(Other.Last->Next.getPointer());
621	    T *IterNode = FirstNode;
622	    do {
623	      // Keep a pointer to the node and increment the iterator.
624	      T *TmpNode = IterNode;
625	      IterNode = static_cast<T *>(IterNode->Next.getPointer());
626	
627	      // Unlink the node and push it back to this list.
628	      TmpNode->Next.setPointerAndInt(TmpNode, true);
629	      push_back(*TmpNode);
630	    } while (IterNode != FirstNode);
631	
632	    Other.Last = nullptr;
633	  }
