682	  iterator begin() {
683	    return Last ? iterator(static_cast<T *>(Last->Next.getPointer())) : end();
684	  }
685	  const_iterator begin() const {
686	    return const_cast<IntrusiveBackList *>(this)->begin();
687	  }
688	  iterator end() { return iterator(); }
689	  const_iterator end() const { return const_iterator(); }
