695	/// A list of DIE values.
696	///
697	/// This is a singly-linked list, but instead of reversing the order of
698	/// insertion, we keep a pointer to the back of the list so we can push in
699	/// order.

980	//===--------------------------------------------------------------------===//
981	/// Represents a compile or type unit.
982	class DIEUnit {
983	  /// The compile unit or type unit DIE. This variable must be an instance of
984	  /// DIE so that we can calculate the DIEUnit from any DIE by traversing the
985	  /// parent backchain and getting the Unit DIE, and then casting itself to a
986	  /// DIEUnit. This allows us to be able to find the DIEUnit for any DIE without
987	  /// having to store a pointer to the DIEUnit in each DIE instance.
988	  DIE Die;
989	  /// The section this unit will be emitted in. This may or may not be set to
990	  /// a valid section depending on the client that is emitting DWARF.
991	  MCSection *Section = nullptr;
992	  uint64_t Offset = 0; /// .debug_info or .debug_types absolute section offset.
993	protected:
994	  virtual ~DIEUnit() = default;
995	
996	public:
997	  LLVM_ABI explicit DIEUnit(dwarf::Tag UnitTag);
998	  DIEUnit(const DIEUnit &RHS) = delete;
999	  DIEUnit(DIEUnit &&RHS) = delete;
1000	  void operator=(const DIEUnit &RHS) = delete;
1001	  void operator=(const DIEUnit &&RHS) = delete;
1002	  /// Set the section that this DIEUnit will be emitted into.
1003	  ///
1004	  /// This function is used by some clients to set the section. Not all clients
1005	  /// that emit DWARF use this section variable.
1006	  void setSection(MCSection *Section) {
1007	    assert(!this->Section);
1008	    this->Section = Section;
1009	  }
1010	
1011	  virtual const MCSymbol *getCrossSectionRelativeBaseAddress() const {
1012	    return nullptr;
1013	  }
1014	
1015	  /// Return the section that this DIEUnit will be emitted into.
1016	  ///
1017	  /// \returns Section pointer which can be NULL.
1018	  MCSection *getSection() const { return Section; }
1019	  void setDebugSectionOffset(uint64_t O) { Offset = O; }
1020	  uint64_t getDebugSectionOffset() const { return Offset; }
1021	  DIE &getUnitDie() { return Die; }
1022	  const DIE &getUnitDie() const { return Die; }
1023	};
