1031	//
1032	class DIELoc : public DIEValueList {
1033	  mutable unsigned Size = 0; // Size in bytes excluding size header.
1034	
1035	public:
1036	  DIELoc() = default;
1037	
1038	  /// Calculate the size of the location expression.
1039	  LLVM_ABI unsigned computeSize(const dwarf::FormParams &FormParams) const;
1040	
1041	  // TODO: move setSize() and Size to DIEValueList.
1042	  void setSize(unsigned size) { Size = size; }
1043	
1044	  /// BestForm - Choose the best form for data.
1045	  ///
1046	  dwarf::Form BestForm(unsigned DwarfVersion) const {
1047	    if (DwarfVersion > 3)
1048	      return dwarf::DW_FORM_exprloc;
1049	    // Pre-DWARF4 location expressions were blocks and not exprloc.
1050	    if ((uint8_t)Size == Size)
1051	      return dwarf::DW_FORM_block1;
1052	    if ((uint16_t)Size == Size)
1053	      return dwarf::DW_FORM_block2;
1054	    if ((uint32_t)Size == Size)
1055	      return dwarf::DW_FORM_block4;
1056	    return dwarf::DW_FORM_block;
1057	  }
